let toastReady=true;

const clock=new THREE.Clock();let elapsed=0;let moveAngle=0;let cameraTarget=new THREE.Vector3();const up=new THREE.Vector3(0,1,0);
function frame(){requestAnimationFrame(frame);const dt=Math.min(clock.getDelta(),.04);elapsed+=dt;
  for(const s of shards){s.mesh.rotation.y+=dt*1.25;s.mesh.rotation.x+=dt*.55;s.mesh.position.y+=(Math.sin(elapsed*2+s.mesh.position.z)*.0015);if(!s.got&&Math.hypot(state.x-s.mesh.position.x,state.z-s.mesh.position.z)<.9&&Math.abs(state.y-s.mesh.position.y)<1.15){s.got=true;scene.remove(s.mesh);state.score++;document.getElementById('score').textContent=String(state.score).padStart(3,'0');showToast('SHARD COLLECTED +1')}}
  let ix=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0),iz=(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0);if(touchActive){ix=touchX;iz=touchY}let mag=Math.hypot(ix,iz);if(mag>1){ix/=mag;iz/=mag}const speed=(keys.has('ShiftLeft')||keys.has('ShiftRight')?9.2:6.5);if(mag>.1){const targetX=ix*speed,targetZ=iz*speed;state.vx+=(targetX-state.vx)*Math.min(1,dt*11);state.vz+=(targetZ-state.vz)*Math.min(1,dt*11);moveAngle=Math.atan2(targetX,targetZ)}else{state.vx*=Math.max(0,1-dt*9);state.vz*=Math.max(0,1-dt*9)}
  if(keys.has('Space')||keys.has('ArrowUp')&&keys.has('ShiftLeft')){if(!frame.spaceLatch)jump();frame.spaceLatch=true}else frame.spaceLatch=false;
  const oldY=state.y;state.x+=state.vx*dt;state.z+=state.vz*dt;state.vy-=22*dt;state.y+=state.vy*dt;state.onGround=false;
  // Land on the first platform crossed from above. Platforms are intentionally solid landing surfaces.
  for(const p of platforms){if(state.x>p.x-p.w/2-.28&&state.x<p.x+p.w/2+.28&&state.z>p.z-p.d/2-.28&&state.z<p.z+p.d/2+.28&&oldY-.02>=p.top&&state.y<=p.top&&state.vy<=0){state.y=p.top;state.vy=0;state.onGround=true}}
  if(state.y< -8)respawn();player.group.position.set(state.x,state.y-.52,state.z);player.group.rotation.y=moveAngle;const swing=mag>.15?Math.sin(elapsed*13)*.42:0;player.legs[0].rotation.x=swing;player.legs[1].rotation.x=-swing;
  // A relentless image that ignores every obstacle and homes directly toward the active runner.
  const hx=state.x-hunter.position.x,hz=state.z-hunter.position.z,dist=Math.hypot(hx,hz),huntSpeed=2.15+Math.min(state.score*.11,1.1);if(dist>.01){hunter.position.x+=hx/dist*huntSpeed*dt;hunter.position.z+=hz/dist*huntSpeed*dt}const bob=Math.sin(elapsed*3.5)*.16;hunter.position.y+=(Math.max(1.05,state.y+1.15+bob)-hunter.position.y)*Math.min(1,dt*3);hunter.rotation.y=Math.atan2(-hx,-hz);face.lookAt(camera.position);orb.scale.setScalar(1+Math.sin(elapsed*4)*.035);
  hunterFlash=Math.max(0,hunterFlash-dt);const danger=Math.max(0,1-dist/6);document.getElementById('danger').style.opacity=String(danger*.55);if(dist<1.38){hunter.position.set(state.x+3,state.y+1,state.z+2);state.escapes++;document.getElementById('escapes').textContent=state.escapes;respawn();showToast('THE IMAGE GOT YOU — RUN AGAIN')}
  // Finish portal can be reached from the raised end platform.
  if(Math.abs(state.x-9)<1.7&&state.z<-41&&state.y>5){state.escapes++;document.getElementById('escapes').textContent=state.escapes;respawn();showToast('COURSE CLEARED · +1 ESCAPE')}
  portal.rotation.y=Math.PI+Math.sin(elapsed*.8)*.13;portal.children[0].rotation.z=elapsed*.35;
  cameraTarget.set(state.x*.46,state.y+2.25,state.z+9.3);camera.position.lerp(cameraTarget,Math.min(1,dt*3.2));camera.lookAt(state.x,state.y+1.1,state.z-2.5);
  const secs=Math.floor((performance.now()-state.started)/1000);document.getElementById('time').textContent=`${String(Math.floor(secs/60)).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`;
  for(const [id,p] of peers){if(performance.now()-p.seen>5000){peers.delete(id);const av=remoteMeshes.get(id);if(av){scene.remove(av.group);remoteMeshes.delete(id)}}}if(performance.now()-lastBroadcast>80){lastBroadcast=performance.now();room.postMessage({type:'runner',id:myId,x:state.x,y:state.y,z:state.z,rot:moveAngle});document.getElementById('room-count').textContent=String(1+peers.size)}
  renderer.render(scene,camera)}
frame();
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});
</script>
</body>
</html>

